0202254","type":"ingredient","index":36,"isNew":true,"ingredient":"<p>Salt</p>","selected_product":null},{"id":"15-split-9-1777312308602-split-11-1777990202255","type":"ingredient","index":37,"isNew":true,"ingredient":"<p>Black pepper</p>","selected_product":null},{"id":"15-split-9-1777312308602-split-12-1777990202255","type":"ingredient","index":38,"isNew":true,"ingredient":"<p>Butter</p>","selected_product":null}],"recipe_directions":[{"id":"0-split-0-1774995433573-split-5-1775059843771-split-9-1776104424006-split-4-1777312151121-split-11-1777312319520-split-0-1777990218708","type":"direction","image":null,"index":35,"direction":"<p>Pat the NY strip steak dry and season generously with salt</p>"},{"id":"0-split-0-1774995433573-split-5-1775059843771-split-9-1776104424006-split-4-1777312151121-split-11-1777312319520-split-1-1777990218708","type":"direction","image":null,"index":36,"direction":"<p>Heat a stainless steel pan over medium low heat for a few minutes</p>"},{"id":"0-split-0-1774995433573-split-5-1775059843771-split-9-1776104424006-split-4-1777312151121-split-11-1777312319520-split-2-1777990218708","type":"direction","image":null,"index":37,"direction":"<p>Sear the steak for about 2-3 minutes per side, depending on thickness, until a deep crust forms.</p>"},{"id":"0-split-0-1774995433573-split-5-1775059843771-split-9-1776104424006-split-4-1777312151121-split-11-1777312319520-split-3-1777990218708","type":"direction","image":null,"index":38,"direction":"<p>Add butter and a smashed garlic clove to the pan, then tilt the pan and baste the steak continuously for 1–2 minutes.</p>"},{"id":"0-split-0-1774995433573-split-5-1775059843771-split-9-1776104424006-split-4-1777312151121-split-11-1777312319520-split-4-1777990218708","type":"direction","image":null,"index":39,"direction":"<p>Remove the steak from the pan and let it rest for at least 5–10 minutes before slicing</p>"},{"id":"0-split-0-1774995433573-split-5-1775059843771-split-9-1776104424006-split-4-1777312151121-split-11-1777312319520-split-5-1777990218708","type":"direction","image":null,"index":40,"direction":"<p>In a small bowl, make the dressing by mixing Greek yogurt, mayonnaise, lemon juice, crumbled blue cheese, minced garlic, salt, and black pepper until smooth and creamy</p>"},{"id":"0-split-0-1774995433573-split-5-1775059843771-split-9-1776104424006-split-4-1777312151121-split-11-1777312319520-split-6-1777990218708","type":"direction","image":null,"index":41,"direction":"<p>In a large bowl, combine chopped romaine, cherry tomatoes, red onion, and walnuts.</p>"},{"id":"0-split-0-1774995433573-split-5-1775059843771-split-9-1776104424006-split-4-1777312151121-split-11-1777312319520-split-7-1777990218708","type":"direction","image":null,"index":42,"direction":"<p>Toss the salad with the dressing until evenly coated</p>"},{"id":"0-split-0-1774995433573-split-5-1775059843771-split-9-1776104424006-split-4-1777312151121-split-11-1777312319520-split-8-1777990218708","type":"direction","image":null,"index":43,"direction":"<p>Slice the rested steak against the grain and serve over the chopped salad</p>"}],"serving_size":"","prep_time":null,"cook_time":null,"recipe_image":"https://cdn.shopify.com/s/files/1/0622/1937/files/Steakhouse_Chopped_Salad_Blog.jpg?v=1777990143","recipe_image_alt_text":"Steakhouse Chopped Salad","iso_prep_time":null,"iso_cook_time":null,"recipe_rating":"3.6666666666666667","enable_rating":true,"rating_count":"3","recipe_note":"","recipe_video":"","recipe_date":"2026-05-05T14:09:16.436+00:00","recipe_calories":null,"recipe_tags":[],"nutrition_data":[],"recipe_id":"2716332","nutrition_serving_size":"","nutrition_template":"horizontal","custom_fields":[]}

