plit-0-1777990325592-split-8-1778869660745","type":"ingredient","index":35,"isNew":true,"ingredient":"<p>Parsley for garnish, if desired</p>","selected_product":null}],"recipe_directions":[{"id":"0-split-0-1774995433573-split-5-1775059843771-split-9-1776104424006-split-4-1777312151121-split-11-1777312319520-split-0-1777990336147-split-0-1778869671309","type":"direction","image":null,"index":36,"direction":"<p>Preheat the oven to 425 degrees fahrenheit.</p>"},{"id":"0-split-0-1774995433573-split-5-1775059843771-split-9-1776104424006-split-4-1777312151121-split-11-1777312319520-split-0-1777990336147-split-1-1778869671309","type":"direction","image":null,"index":37,"direction":"<p>Boil your baby potatoes for 10-20 minutes, or until they are fork tender. While your potatoes are cooking, place your Jelly Roll pan in the oven to preheat.</p>"},{"id":"0-split-0-1774995433573-split-5-1775059843771-split-9-1776104424006-split-4-1777312151121-split-11-1777312319520-split-0-1777990336147-split-2-1778869671310","type":"direction","image":null,"index":38,"direction":"<p>Drain the potatoes and then use the heel of your hand or a small bowl to gently smash the potatoes.</p>"},{"id":"0-split-0-1774995433573-split-5-1775059843771-split-9-1776104424006-split-4-1777312151121-split-11-1777312319520-split-0-1777990336147-split-3-1778869671310","type":"direction","image":null,"index":39,"direction":"<p>Take the Jelly Roll pan out of the oven and drizzle with olive oil. Sprinkle half of the oregano, garlic salt, and black pepper on the pan and place the potatoes on the pan. Drizzle the top of the potatoes with olive oil and sprinkle the remainder of the oregano, garlic salt, and black pepper on the top of the potatoes.</p>"},{"id":"0-split-0-1774995433573-split-5-1775059843771-split-9-1776104424006-split-4-1777312151121-split-11-1777312319520-split-0-1777990336147-split-4-1778869671310","type":"direction","image":null,"index":40,"direction":"<p>Return the pan to the oven and cook for 10-15 minutes, then flipping and cooking another 10-15 minutes, or until golden and crispy.</p>"},{"id":"0-split-0-1774995433573-split-5-1775059843771-split-9-1776104424006-split-4-1777312151121-split-11-1777312319520-split-0-1777990336147-split-5-1778869671310","type":"direction","image":null,"index":41,"direction":"<p>Remove the smashed potatoes from the oven and place on a platter. Crumble your feta cheese on top of the potatoes and squeeze some lemon juice on top. Garnish with additional dried oregano, pepper, and salt as desired. Top with fresh parsley, if desired</p>"}],"serving_size":"","prep_time":null,"cook_time":null,"recipe_image":"https://cdn.shopify.com/s/files/1/0622/1937/files/Greek_Potatoes_Blog.jpg?v=1778868956","recipe_image_alt_text":"Crispy Smashed Feta Potatoes","iso_prep_time":null,"iso_cook_time":null,"recipe_rating":"1.00000000000000000000","enable_rating":true,"rating_count":"4","recipe_note":"","recipe_video":"","recipe_date":"2026-05-15T18:10:19.913+00:00","recipe_calories":null,"recipe_tags":[],"nutrition_data":[],"recipe_id":"2725011","nutrition_serving_size":"","nutrition_template":"horizontal","custom_fields":[]}

