null}],"recipe_directions":[{"id":"0-split-0-1781284156563","type":"direction","image":null,"index":1,"direction":"<p>Chop your bacon strips into pieces and fry in your stock pot. Once crispy, remove from the pot and set aside.</p>"},{"id":"0-split-1-1781284156563","type":"direction","image":null,"index":2,"direction":"<p>Using the remaining bacon grease in the pot, add your chopped onion, chopped zucchini, corn kernels, and garlic to the pan and saute for 4-5 minutes.</p>"},{"id":"0-split-2-1781284156563","type":"direction","image":null,"index":3,"direction":"<p>Add your chopped potatoes to the pot, as well as 4 cups of chicken broth and ½ teaspoon of paprika.</p>"},{"id":"0-split-3-1781284156563","type":"direction","image":null,"index":4,"direction":"<p>Cover and bring to a boil for about 10-15 minutes.</p>"},{"id":"0-split-4-1781284156564","type":"direction","image":null,"index":5,"direction":"<p>Once the potatoes are fork tender, turn off the heat and use an immersion blender to blend about half of the chowder.</p>"},{"id":"0-split-5-1781284156564","type":"direction","image":null,"index":6,"direction":"<p>Mix in the cup of heavy cream, shredded white cheddar cheese, and hot sauce.</p>"},{"id":"0-split-6-1781284156564","type":"direction","image":null,"index":7,"direction":"<p>Top with bacon bits, fresh chives, and a drizzle of heavy cream.</p>"}],"serving_size":"","prep_time":null,"cook_time":null,"recipe_image":"https://cdn.shopify.com/s/files/1/0622/1937/files/Chowder_Blog_Photo.jpg?v=1781284067","recipe_image_alt_text":"Zucchini & Corn Chowder","iso_prep_time":null,"iso_cook_time":null,"recipe_rating":"2.3333333333333333","enable_rating":true,"rating_count":"3","recipe_note":"","recipe_video":"","recipe_date":"2026-06-12T17:08:08.609+00:00","recipe_calories":null,"recipe_tags":[],"nutrition_data":[],"recipe_id":"2751565","nutrition_serving_size":"","nutrition_template":"horizontal","custom_fields":[]}
